package org.opensearch.supervisor.model.index;

import org.junit.jupiter.api.Test;
import org.opensearch.supervisor.model.status.Replication;

import java.nio.charset.StandardCharsets;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Parsing the control plane's index document, checked against the real example in {@code KEY_LAYOUT.md}.
 *
 * <p>That file was generated by exercising a real control plane and dumping what it wrote, so these are
 * tests against the other service's actual output rather than against our model of it — which is the
 * distinction {@code WORKING_NOTES.md} warns about: unit tests and implementation share the author's
 * assumptions, so a misread field makes both wrong together and agreeing.
 */
class IndexConfigTests {

    /** Copied verbatim from KEY_LAYOUT.md. */
    private static final String REAL_DOCUMENT = """
        {
          "index": "my-index",
          "uuid": "uzKxLWZu4nPSrTknEcDpoA",
          "creation_date": "1788969977933",
          "state": "close",
          "settings": {
            "index.number_of_replicas": "1",
            "index.number_of_shards": "3",
            "index.replication.type": "DOCUMENT",
            "index.verified_before_close": "true"
          },
          "mappings": { "properties": { "host": { "type": "keyword" } } }
        }
        """;

    private static IndexConfig parse(String json) {
        return IndexConfig.parse(json.getBytes(StandardCharsets.UTF_8), 3041);
    }

    @Test
    void parsesTheDocumentTheControlPlaneActuallyWrites() {
        IndexConfig config = parse(REAL_DOCUMENT);

        assertEquals("my-index", config.name());
        assertEquals("uzKxLWZu4nPSrTknEcDpoA", config.uuid());
        assertFalse(config.open(), "state was close");
        assertEquals(3, config.numberOfShards());
        assertEquals(1, config.numberOfReplicas());
        assertEquals(Replication.DOCUMENT, config.replication());
        assertEquals(3041, config.configRevision());
    }

    @Test
    void settingsAreStringsAndMustBeReadAsStrings() {
        // KEY_LAYOUT.md is explicit: "3", not 3; "true", not true. Jackson's asInt() on a string node
        // answers 0, so reading these as numbers would give every index one shard and no replicas --
        // silently, and with a plausible-looking result.
        IndexConfig config = parse("""
            {"index":"i","uuid":"u","settings":{"index.number_of_shards":"12","index.number_of_replicas":"4"}}
            """);

        assertEquals(12, config.numberOfShards());
        assertEquals(4, config.numberOfReplicas());
    }

    @Test
    void anAbsentStateMeansOpen() {
        assertTrue(parse("{\"index\":\"i\",\"uuid\":\"u\",\"settings\":{}}").open());
    }

    @Test
    void defaultsApplyWhenSettingsAreAbsent() {
        // A document with no shard count is not a broken document; OpenSearch's own default is one shard
        // and no replicas, and refusing to read the index would be a worse answer than assuming it.
        IndexConfig config = parse("{\"index\":\"i\",\"uuid\":\"u\"}");

        assertEquals(1, config.numberOfShards());
        assertEquals(0, config.numberOfReplicas());
        assertEquals(Replication.SEGMENT, config.replication(), "segment replication is the intended default");
    }

    @Test
    void aDocumentWithoutAUuidIsRefusedRatherThanGuessedAt() {
        // The uuid is the identity. Inventing one, or falling back to the name, would let a recreated index
        // inherit its predecessor's shards.
        assertThrows(IllegalArgumentException.class, () -> parse("{\"index\":\"i\",\"settings\":{}}"));
        assertThrows(IllegalArgumentException.class, () -> parse("{\"uuid\":\"u\",\"settings\":{}}"));
    }

    @Test
    void anUnparseableShardCountFailsThatIndexLoudly() {
        assertThrows(IllegalArgumentException.class, () -> parse("""
            {"index":"i","uuid":"u","settings":{"index.number_of_shards":"lots"}}
            """));
    }

    @Test
    void desiredCopiesCountsPrimariesAndReplicas() {
        IndexConfig config = parse("""
            {"index":"i","uuid":"u","settings":{"index.number_of_shards":"3","index.number_of_replicas":"2"}}
            """);

        assertEquals(3, config.copiesPerShard());
        assertEquals(9, config.desiredCopies());
    }

    @Test
    void aClosedIndexWantsNoCopies() {
        assertEquals(0, parse(REAL_DOCUMENT).desiredCopies());
    }

    @Test
    void theTestHelperProducesSomethingTheParserAccepts() {
        // toDocument exists so tests and fake-node can write plausible index documents. If it drifted from
        // the parser, every test using it would pass against a shape the control plane never writes.
        byte[] document = IndexConfig.toDocument(
            "logs", "uuuuuu", true, IndexConfig.settingsOf(2, 1, Replication.SEGMENT)
        );
        IndexConfig config = IndexConfig.parse(document, 7);

        assertEquals("logs", config.name());
        assertEquals("uuuuuu", config.uuid());
        assertTrue(config.open());
        assertEquals(2, config.numberOfShards());
        assertEquals(1, config.numberOfReplicas());
        assertEquals(Replication.SEGMENT, config.replication());
        assertEquals(7, config.configRevision());
    }
}
